{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; its absence from the report does not establish that it never occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score provides no evidence of consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring are specified as 100 unfamiliar puzzles with exact-grid scoring. The score describes the reported run within the intended scope. Repeated-run consistency and the conditions needed to assess fair system comparisons remain undocumented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "A single evaluation cannot establish repeated-run stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "The puzzle set and scoring rule support interpreting 70% as performance in the single evaluation. The documented lack of repetition leaves consistency unassessed and limits confidence in comparisons based on that run."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The report explicitly describes repeated evaluations under matching conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated evaluations support consistency under the specified conditions and stated stability criterion. This evidence concerns the tested system and puzzles; it does not establish consistency under changed conditions or performance beyond the intended puzzle comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated-run testing under the same conditions is explicitly documented."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum of two percentage points for stability."
        }
      ],
      "instrument_review": "The repeated evaluations document a consistency problem under the report's own criterion. The isolated 70% score cannot adequately represent the reported variation. Comparisons should account for this variation; its cause remains unexplained."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance does not document repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence about score consistency."
        }
      ],
      "instrument_review": "Installation instructions document setup, but they do not resolve missing evidence about repeated-run consistency. The 70% score remains a single reported result for the specified puzzles and scoring rule."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison matches the intended use on the evaluated grid puzzles. Exact-grid scoring and fixed instructions are specified, while other conditions affecting fairness and repeated-run consistency are not. Broader interpretations lack supporting evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on these evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The stated intended use does not supply the missing evidence across domains."
        }
      ],
      "instrument_review": "The intended selection use exceeds the demonstrated scope: the results compare grid-puzzle performance but do not establish general intelligence across domains. Fixed instructions and exact scoring clarify the narrow comparison; broader coverage, consistency, and other fairness conditions remain unestablished."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no reported evidence that A improves actual workshop decisions relative to B."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports higher correctness with A in the studied workshop, with a reported difference interval entirely above zero."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings do not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The later preregistered, randomized trial, blinded correctness checks, and reported uncertainty support the intended choice for decision correctness in this workshop. Evidence is limited to the studied setting and conditions; effects on time, safety, and other workshops remain unestablished."
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was distinguished from explicit contradiction, and each case was assessed independently."
}
